(function(){'use strict';const SELECTOR = '[data-gallery] img,[data-gallery] .thumb,.property-image,.lightbox-trigger';class ImageGallery{constructor(){this.images = [];this.current = 0;this.zoom = 1;this.slideshow = null;this.touchStartX = 0;this.touchEndX = 0;this.isOpen = false;this.overlay = null;this.init();}init(){this.collectImages();this.bindDocumentClicks();this.bindKeyboard();}collectImages(){document.querySelectorAll('[data-gallery]').forEach(group =>{const imgs = group.querySelectorAll('img');imgs.forEach((img,idx)=>{img.style.cursor = 'zoom-in';img.dataset.galleryGroup = group.dataset.gallery;img.dataset.galleryIndex = idx;});});}bindDocumentClicks(){document.addEventListener('click',(e)=>{const target = e.target.closest('img[data-gallery-group],.lightbox-trigger,[data-gallery] img,[data-gallery] .thumb,.property-image');if(!target)return;e.preventDefault();this.openGroup(target);});}openGroup(target){const group = target.dataset.galleryGroup;if(!group){this.images = [{src:target.src || target.dataset.src,caption:target.alt || target.title || ''}];this.current = 0;}else{const groupEl = document.querySelector('[data-gallery="' + group + '"]');this.images = [];if(groupEl){groupEl.querySelectorAll('img').forEach(img =>{const fullSrc = img.dataset.full || img.src;this.images.push({src:fullSrc,caption:img.alt || img.dataset.caption || img.title || ''});});}this.current = parseInt(target.dataset.galleryIndex || '0',10);}if(this.images.length === 0)return;this.build();this.show();}bindKeyboard(){document.addEventListener('keydown',(e)=>{if(!this.isOpen)return;if(e.key === 'Escape')this.hide();else if(e.key === 'ArrowRight')this.next();else if(e.key === 'ArrowLeft')this.prev();else if(e.key === '+' || e.key === '=')this.zoomIn();else if(e.key === '-')this.zoomOut();});}build(){if(this.overlay)this.overlay.remove();this.overlay = document.createElement('div');this.overlay.className = 'image-lightbox';this.overlay.innerHTML = ` <div class="lightbox-backdrop"></div> <button type="button" class="lightbox-close" aria-label="Close">&times;</button> <button type="button" class="lightbox-nav lightbox-prev" aria-label="Previous">&#10094;</button> <button type="button" class="lightbox-nav lightbox-next" aria-label="Next">&#10095;</button> <div class="lightbox-stage"> <img class="lightbox-image" alt=""> </div> <div class="lightbox-caption"></div> <div class="lightbox-controls"> <button type="button" class="lightbox-btn" data-action="zoom-out" title="Zoom out">-</button> <button type="button" class="lightbox-btn" data-action="zoom-in" title="Zoom in">+</button> <button type="button" class="lightbox-btn" data-action="reset" title="Reset zoom">1x</button> <button type="button" class="lightbox-btn" data-action="play" title="Play slideshow">&#9658;</button> <button type="button" class="lightbox-btn" data-action="download" title="Download">&#11015;</button> </div> <div class="lightbox-counter"></div> <div class="lightbox-thumbs"></div> `;document.body.appendChild(this.overlay);this.overlay.querySelector('.lightbox-backdrop').addEventListener('click',()=> this.hide());this.overlay.querySelector('.lightbox-close').addEventListener('click',()=> this.hide());this.overlay.querySelector('.lightbox-prev').addEventListener('click',()=> this.prev());this.overlay.querySelector('.lightbox-next').addEventListener('click',()=> this.next());this.overlay.querySelector('.lightbox-image').addEventListener('click',()=> this.zoomIn());this.overlay.querySelector('.lightbox-image').addEventListener('dblclick',()=>{this.zoom = this.zoom === 2 ? 1:2;this.applyZoom();});this.overlay.querySelectorAll('.lightbox-btn').forEach(btn =>{btn.addEventListener('click',()=> this.handleAction(btn.dataset.action));});const stage = this.overlay.querySelector('.lightbox-stage');stage.addEventListener('touchstart',(e)=>{this.touchStartX = e.changedTouches[0].screenX;},{passive:true});stage.addEventListener('touchend',(e)=>{this.touchEndX = e.changedTouches[0].screenX;this.handleSwipe();},{passive:true});}handleSwipe(){const diff = this.touchStartX - this.touchEndX;if(Math.abs(diff)> 50){if(diff > 0)this.next();else this.prev();}}handleAction(action){switch(action){case 'zoom-in':this.zoomIn();break;case 'zoom-out':this.zoomOut();break;case 'reset':this.zoom = 1;this.applyZoom();break;case 'play':this.toggleSlideshow();break;case 'download':this.download();break;}}zoomIn(){this.zoom = Math.min(this.zoom + 0.25,4);this.applyZoom();}zoomOut(){this.zoom = Math.max(this.zoom - 0.25,0.5);this.applyZoom();}applyZoom(){const img = this.overlay.querySelector('.lightbox-image');img.style.transform = `scale(${this.zoom})`;}toggleSlideshow(){const btn = this.overlay.querySelector('[data-action="play"]');if(this.slideshow){clearInterval(this.slideshow);this.slideshow = null;btn.innerHTML = '&#9658;';}else{btn.innerHTML = '&#10074;&#10074;';this.slideshow = setInterval(()=> this.next(),4000);}}download(){const img = this.images[this.current];if(!img)return;const a = document.createElement('a');a.href = img.src;a.download = img.caption || 'image';a.target = '_blank';document.body.appendChild(a);a.click();a.remove();}show(){this.isOpen = true;document.body.classList.add('lightbox-open');this.overlay.classList.add('active');this.render();}hide(){this.isOpen = false;document.body.classList.remove('lightbox-open');if(this.overlay)this.overlay.classList.remove('active');if(this.slideshow){clearInterval(this.slideshow);this.slideshow = null;}this.zoom = 1;setTimeout(()=>{if(this.overlay && !this.isOpen){this.overlay.remove();this.overlay = null;}},300);}next(){this.current =(this.current + 1)% this.images.length;this.render();}prev(){this.current =(this.current - 1 + this.images.length)% this.images.length;this.render();}render(){if(!this.overlay)return;const img = this.images[this.current];const imgEl = this.overlay.querySelector('.lightbox-image');imgEl.src = img.src;imgEl.alt = img.caption;this.overlay.querySelector('.lightbox-caption').textContent = img.caption || '';this.overlay.querySelector('.lightbox-counter').textContent =(this.current + 1)+ ' / ' + this.images.length;this.applyZoom();const thumbs = this.overlay.querySelector('.lightbox-thumbs');thumbs.innerHTML = '';this.images.forEach((entry,idx)=>{const t = document.createElement('img');t.src = entry.src;t.alt = entry.caption;t.className = idx === this.current ? 'active':'';t.loading = 'lazy';t.addEventListener('click',()=>{this.current = idx;this.render();});thumbs.appendChild(t);});}}if(document.readyState === 'loading'){document.addEventListener('DOMContentLoaded',()=>{window.imageGallery = new ImageGallery();});}else{window.imageGallery = new ImageGallery();}})();